return [
  {
    json: {
      is_duplicate: false,
      is_duplicate_flag: '',
      iam_context: { realm: 'default' },
      actor: { name: 'test-user', email: 'test-user@example.com' },
      reply_target: {
        source: 'zulip',
        realm: 'default',
        stream: 'test',
        topic: 'cir-intake-test',
        url: 'https://zulip.example/#narrow/stream/1/topic/cir-intake-test/near/123'
      },
      normalized_event: {
        source: 'zulip',
        text: '○○ができるようになってください。'
      }
    }
  }
];

const crypto = require('crypto');

const base = $json ?? {};
const normalized = (base.normalized_event && typeof base.normalized_event === 'object') ? base.normalized_event : {};
const replyTarget = (base.reply_target && typeof base.reply_target === 'object') ? base.reply_target : {};
const source = String(normalized.source ?? base.source ?? replyTarget.source ?? 'unknown');
const isDuplicate = Boolean(base.is_duplicate) || String(base.is_duplicate_flag ?? '') === 'true';

const NL = String.fromCharCode(10);
const CR = String.fromCharCode(13);

function truthy(v) {
  const raw = String(v ?? '').trim().toLowerCase();
  return ['1', 'true', 'yes', 'y', 'on'].includes(raw);
}

function trimSlash(v) {
  return String(v ?? '').replace(/\/+$/, '');
}

function pickEnv(...keys) {
  for (const k of keys) {
    const v = $env?.[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v);
  }
  return '';
}

function stripHtml(t) {
  return String(t ?? '')
    .replace(/<style[\s\S]*?>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

function stripMention(t) {
  return String(t ?? '')
    .replace(/^@\*\*[^*]+\*\*\s*/, '')
    .replace(/^@\S+\s*/, '');
}

function firstLine(t) {
  const s = String(t ?? '').split(CR).join('').split(NL).map((l) => l.trim()).find(Boolean);
  return s || '';
}

function normalizeText(t) {
  return String(t ?? '').normalize('NFKC').toLowerCase().replace(/\s+/g, ' ').trim();
}

const raw = String(normalized.text ?? normalized.original_text ?? '').trim();
const plain = stripMention(stripHtml(raw));
const line = firstLine(plain);

const fullNorm = normalizeText(plain);
const polite = /(ください|お願いします|してほしい|したい|お願い)/.test(fullNorm);
const hasImproveToken = /(できるようになって|できるようにして|改善|要望|追加して|実装して|対応して|対応できるように)/.test(fullNorm);
const isImproveRequest = (polite && hasImproveToken) || /できるようになってください/.test(fullNorm);

if (source !== 'zulip' || isDuplicate || !isImproveRequest) {
  return [{ json: { ...base, ok: false, reason: 'not_target', source, is_duplicate: isDuplicate, is_improvement_request: isImproveRequest } }];
}

const fingerprintBase = normalizeText(line || plain)
  .replace(/[\s\u3000]+/g, ' ')
  .trim()
  .replace(/[\s\u3000、。・（）()［］\[\]「」『』【】{}<>＜＞…‥]/g, '');
const dedupeKey = `CIR-AIOPS-REQ:${crypto.createHash('sha256').update(fingerprintBase, 'utf8').digest('hex')}`;

const cirLabel = String(pickEnv('ITSM_CIR_LABEL', 'AIOPS_CIR_LABEL') || 'ITSM/継続的改善').trim() || 'ITSM/継続的改善';
const statusNewLabel = String(pickEnv('ITSM_CIR_STATUS_NEW_LABEL', 'AIOPS_CIR_STATUS_NEW_LABEL') || '状態/New').trim() || '状態/New';

const apiBase = trimSlash(pickEnv('N8N_GITLAB_API_BASE_URL', 'GITLAB_API_BASE_URL'));
const webBase = trimSlash(pickEnv('N8N_GITLAB_WEB_BASE_URL', 'GITLAB_WEB_BASE_URL') || apiBase.replace(/\/api\/v4$/, ''));
const projectRef = String(pickEnv('N8N_GITLAB_GENERAL_MANAGEMENT_PROJECT_ID', 'GITLAB_GENERAL_MANAGEMENT_PROJECT_ID', 'N8N_GITLAB_GENERAL_MANAGEMENT_PROJECT_PATH', 'GITLAB_GENERAL_MANAGEMENT_PROJECT_PATH') || '').trim();

const projectEnc = projectRef ? encodeURIComponent(projectRef) : '(unset)';
const searchUrl = apiBase && projectRef
  ? `${apiBase}/projects/${projectEnc}/issues?` + new URLSearchParams({ state: 'opened', labels: cirLabel, search: dedupeKey, per_page: '20' }).toString()
  : null;
const createUrl = apiBase && projectRef
  ? `${apiBase}/projects/${projectEnc}/issues`
  : null;

const content = [
  '承りました。できるかどうか検討し、別途お知らせします。',
  '（テスト: dry-run / GitLab API は呼びません）'
].join(NL);

return [{
  json: {
    ...base,
    ok: true,
    content,
    cir_intake_dry_run: true,
    cir_intake_preview: {
      dedupe_key: dedupeKey,
      title_preview: `CIR: 改善要望 - ${line || plain || '改善要望'}`,
      labels: [cirLabel, statusNewLabel],
      planned: {
        search_url: searchUrl,
        create_url: createUrl
      },
      env_hints: {
        needs: ['N8N_GITLAB_API_BASE_URL', 'N8N_GITLAB_TOKEN', 'N8N_GITLAB_GENERAL_MANAGEMENT_PROJECT_(ID|PATH)'],
        has_api_base_url: Boolean(apiBase),
        has_project_ref: Boolean(projectRef)
      }
    }
  }
}];
